    image_patch = ImagePatch(image)
    gray_matter_patches = image_patch.find("gray matter")
    red_platform_patches = image_patch.find("red platform")
    if not gray_matter_patches or not red_platform_patches:
        return image_patch
    for gm_patch in gray_matter_patches:
        for rp_patch in red_platform_patches:
            if gm_patch.overlaps_with(rp_patch.left, rp_patch.lower, rp_patch.right, rp_patch.upper):
                return gm_patch
    return gray_matter_patches[0] if gray_matter_patches else red_platform_patches[0]

